// Browser-only design data. No native capture, file access or OS permissions.
const copycatSetupBridgeURL = document.currentScript.src;
let previewProject=null;const listeners=[];
const snapshot=()=>({revision:0,project:previewProject,saveState:'saved',unsaved:false,error:'',updates:{enabled:false},desktop:{active:false},bridge:null});
window.guides={subscribe:callback=>{listeners.push(callback);return ()=>{};},request:async(name,args)=>{
 if(name==='state')return snapshot();if(name==='list')return [];
 if(!window.matiqPrototypeSetupReady)throw Error('Finish Copycat setup before using this tool.');
 if(name==='new'){previewProject={format:'matiq-guides',version:1,guide:{id:crypto.randomUUID(),title:'Untitled guide',description:'',steps:[]},assets:{}};return snapshot();}
 if(name==='save'){previewProject=structuredClone(args);return snapshot();}
 if(name==='dirty'||name==='draft')return {saved:true};
 throw Error('Prototype only: '+name+' does not access your files, browser, or desktop.');
}};

// First-run design review uses the shared shell preview; production behavior is unchanged.
document.addEventListener('DOMContentLoaded',()=>{const script=document.createElement('script');script.src=new URL('../.matiq-shell/setup-preview.js',copycatSetupBridgeURL).href;script.onload=()=>window.matiqSetupPreview({"id": "com.matiq.guides", "name": "Copycat", "steps": [{"id": "storage", "title": "Your guides stay on this Mac", "body": "Guides, screenshots, edits and exports are stored locally. No account or model download is needed. Imports and sharing happen only when you choose.", "kind": "review", "label": "I reviewed local storage and sharing."}, {"id": "capture", "title": "Review capture scope", "body": "Desktop recording follows your explicit Start and Stop actions. A selected-window scope and manual guide editing are also available.", "kind": "choice", "label": "Default capture mode", "options": [["desktop", "Desktop workflow across apps"], ["window", "One selected application window"]]}, {"id": "screen", "title": "Allow Screen Recording", "body": "Enable Screen Recording for {app}. This permits screenshots during your recording; setup itself does not record your desktop.", "kind": "check", "permission": true, "action": "Preview Screen Recording check", "success": "Screen Recording access verified."}, {"id": "accessibility", "title": "Allow Accessibility", "body": "Enable Accessibility for {app} so Copycat can identify controls and describe workflow actions. Normal typed characters are not stored as instructions.", "kind": "check", "permission": true, "action": "Preview Accessibility check", "success": "Accessibility access verified."}, {"id": "privacy", "title": "Review screenshots before sharing", "body": "Screenshots can contain private information. Review, crop and redact each guide before exporting. Automatic masking cannot guarantee that every secret is hidden.", "kind": "review", "label": "I understand that I must review screenshots and instructions before sharing."}, {"id": "browser", "title": "Optional browser extensions", "body": "Desktop recording works without an extension. Choose an optional extension only if you want its browser-specific capture controls.", "kind": "choice", "label": "Browser extension", "options": [["none", "Skip extensions"], ["chrome", "Set up Chrome extension"], ["edge", "Set up Edge extension"], ["firefox", "Set up Firefox extension"]]}, {"id": "updates", "title": "Review updates and quitting", "body": "{app} owns updates for this installed tool. Save guides and stop recording before restarting. A denied first capture must leave no active recording and must allow normal Quit.", "kind": "review", "label": "I reviewed update ownership and safe shutdown."}, {"id": "ready", "title": "Ready to use Copycat", "body": "Required setup is finished. You can revisit settings later; recording still requires your explicit Start.", "kind": "summary"}]});document.head.append(script);});
